<div class="ost-player" id="ostPlayer"><div class="ost-player-track"><img id="ostPlayerImage" src="<?php echo e(asset('users/img/weblogo.png')); ?>" alt="" onerror="this.onerror=null;this.src='<?php echo e(asset('users/img/play-default.png')); ?>';"><div><strong id="ostPlayerTitle">Select a song</strong><span id="ostPlayerArtist">SOUND</span></div></div><div class="ost-player-controls"><button type="button" id="ostPrev" class="ost-control"><i class="fa-solid fa-backward-step"></i></button><button type="button" id="ostPlayPause" class="ost-control ost-control-main"><i class="fa-solid fa-play"></i></button><button type="button" id="ostNext" class="ost-control"><i class="fa-solid fa-forward-step"></i></button></div><div class="ost-progress-wrap"><span id="ostCurrent">0:00</span><input id="ostProgress" type="range" min="0" max="100" value="0"><span id="ostDuration">0:00</span></div><audio id="ostAudio" preload="metadata"></audio></div>
<script>
document.addEventListener('DOMContentLoaded',()=>{const cards=[...document.querySelectorAll('.ost-track')],playable=cards.filter(c=>c.dataset.audio),audio=document.getElementById('ostAudio'),player=document.getElementById('ostPlayer'),title=document.getElementById('ostPlayerTitle'),artist=document.getElementById('ostPlayerArtist'),image=document.getElementById('ostPlayerImage'),pp=document.getElementById('ostPlayPause'),prev=document.getElementById('ostPrev'),next=document.getElementById('ostNext'),progress=document.getElementById('ostProgress'),current=document.getElementById('ostCurrent'),duration=document.getElementById('ostDuration');let index=-1;const fmt=v=>Number.isFinite(v)?`${Math.floor(v/60)}:${Math.floor(v%60).toString().padStart(2,'0')}`:'0:00';const icon=on=>pp.innerHTML=`<i class="fa-solid ${on?'fa-pause':'fa-play'}"></i>`;const load=(i,auto=true)=>{if(!playable.length)return;index=(i+playable.length)%playable.length;const c=playable[index];audio.src=c.dataset.audio;title.textContent=c.dataset.title;artist.textContent=c.dataset.artist;image.src=c.dataset.image;player.classList.add('active');cards.forEach(x=>x.classList.remove('is-playing'));c.classList.add('is-playing');if(auto)audio.play().then(()=>icon(true)).catch(()=>icon(false));else icon(false)};cards.forEach(c=>c.querySelector('.ost-play-btn')?.addEventListener('click',e=>{e.stopPropagation();let i=playable.indexOf(c);if(i<0)return;if(index===i&&!audio.paused){audio.pause();icon(false)}else if(index===i)audio.play().then(()=>icon(true));else load(i,true)}));pp.onclick=()=>index<0?load(0,true):audio.paused?audio.play().then(()=>icon(true)):(audio.pause(),icon(false));prev.onclick=()=>load(index-1,true);next.onclick=()=>load(index+1,true);audio.onloadedmetadata=()=>duration.textContent=fmt(audio.duration);audio.ontimeupdate=()=>{current.textContent=fmt(audio.currentTime);progress.value=audio.duration?audio.currentTime/audio.duration*100:0};audio.onplay=()=>icon(true);audio.onpause=()=>icon(false);audio.onended=()=>load(index+1,true);progress.oninput=()=>{if(audio.duration)audio.currentTime=progress.value/100*audio.duration}});
</script>
